/* VCD dumping functions */
MOD_mkFp32MulCoreTestbench & mkFp32MulCoreTestbench_backing(tSimStateHdl simHdl)
{
  static MOD_mkFp32MulCoreTestbench *instance = NULL;
  if (instance == NULL)
  {
    vcd_set_backing_instance(simHdl, true);
    instance = new MOD_mkFp32MulCoreTestbench(simHdl, "top", NULL);
    vcd_set_backing_instance(simHdl, false);
  }
  return *instance;
}
